"""Evaluate a model on the hand-reviewed gold set and save results/<model>.json.

Built-in models:
- gemini-teacher: the teacher's labels for the gold reviews (data/gold/gemini_labels.jsonl).
  Latency comes from the labeling request log (batches of 20, network included).
- tfidf-logreg: TF-IDF + logistic regression trained on data/labeled/train.jsonl
  (run scripts/make_splits.py first); validation metrics are saved too.

Any other model is evaluated from a raw predictions JSONL ({"review_id", "raw",
"latency_s"} per line, e.g. generated by notebooks/02_finetune.ipynb), parsed and scored
with the same code as the built-in models.

Per-review predictions are saved to results/predictions/<model>.jsonl for error analysis.

Examples:
    uv run python scripts/evaluate.py --model gemini-teacher
    uv run python scripts/evaluate.py --model tfidf-logreg
    uv run python scripts/evaluate.py --model qwen2.5-0.5b-lora \\
        --predictions results/predictions/qwen2.5-0.5b-lora_raw.jsonl \\
        --config results/predictions/qwen2.5-0.5b-lora_config.json
"""

import argparse
import json
import time
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from review_distill.baselines import TfidfLogRegBaseline
from review_distill.data import LABELED_DIR, PROJECT_ROOT
from review_distill.gold import (
    GEMINI_GOLD_PATH,
    GOLD_LABELS_PATH,
    diagnosis_from_record,
    load_labels,
)
from review_distill.inference import parse_diagnosis
from review_distill.labeling import append_jsonl, read_jsonl
from review_distill.metrics import compute_metrics, latency_stats
from review_distill.sampling import GOLD_REVIEWS_PATH, load_sample
from review_distill.schema import ReviewDiagnosis
from review_distill.splits import TRAIN_PATH, VAL_PATH, load_split

RESULTS_DIR = PROJECT_ROOT / "results"
TEACHER_REQUESTS_PATH = LABELED_DIR / "requests_gold.jsonl"

Predictions = list[ReviewDiagnosis | None]


def load_gold() -> tuple[list[str], list[str], list[ReviewDiagnosis]]:
    """Gold review ids, texts and reviewed labels, in gold_reviews.csv order."""
    reviews = load_sample(GOLD_REVIEWS_PATH)
    labels = load_labels(GOLD_LABELS_PATH)
    missing = set(reviews["review_id"]) - set(labels)
    if missing:
        raise SystemExit(f"{len(missing)} gold reviews have no reviewed label")
    ids = list(reviews["review_id"])
    return ids, list(reviews["text"]), [diagnosis_from_record(labels[i]) for i in ids]


def split_labels(path: Path) -> tuple[list[str], list[ReviewDiagnosis]]:
    df = load_split(path)
    return list(df["text"]), [diagnosis_from_record(r) for r in df.to_dict("records")]


def eval_teacher(ids: list[str], texts: list[str]) -> tuple[Predictions, dict[str, Any]]:
    labels = load_labels(GEMINI_GOLD_PATH)
    preds = [diagnosis_from_record(labels[i]) if i in labels else None for i in ids]
    first = next(iter(labels.values()))
    config: dict[str, Any] = {
        k: first.get(k) for k in ("model", "prompt_version", "thinking_level")
    }
    config |= {"temperature": 0.0, "seed": 42, "batch_size": 20}

    requests = [r for r in read_jsonl(TEACHER_REQUESTS_PATH) if r.get("ok")]
    if requests:
        # Successful API call time per review (retries/backoff after 503s excluded).
        per_review = [
            r["last_call_s"] / r["n_reviews"] for r in requests for _ in range(r["n_reviews"])
        ]
        n = sum(r["n_valid"] for r in requests)
        config["latency_mode"] = "batched (20 reviews/request, API call incl. network)"
        config["tokens_per_1000_reviews"] = {
            "prompt": round(1000 * sum(r["prompt_tokens"] or 0 for r in requests) / n),
            "output": round(1000 * sum(r["output_tokens"] or 0 for r in requests) / n),
        }
        config["latency"] = latency_stats(per_review)
    return preds, config


def eval_tfidf(ids: list[str], texts: list[str]) -> tuple[Predictions, dict[str, Any]]:
    if not TRAIN_PATH.exists():
        raise SystemExit(f"{TRAIN_PATH} not found; run scripts/make_splits.py first")
    train_texts, train_labels = split_labels(TRAIN_PATH)
    model = TfidfLogRegBaseline()
    start = time.perf_counter()
    model.fit(train_texts, train_labels)
    config: dict[str, Any] = model.config()
    config["train_size"] = len(train_texts)
    config["train_s"] = round(time.perf_counter() - start, 2)

    val_texts, val_labels = split_labels(VAL_PATH)
    config["val_metrics"] = compute_metrics(val_labels, model.predict(val_texts))

    preds, latencies = [], []
    for text in texts:  # one review at a time, to measure per-request latency
        start = time.perf_counter()
        (pred,) = model.predict([text])
        latencies.append(time.perf_counter() - start)
        preds.append(pred)
    config["latency_mode"] = "single review per call, CPU"
    config["latency"] = latency_stats(latencies)
    return preds, config


def eval_predictions_file(
    path: Path, ids: list[str]
) -> tuple[Predictions, dict[str, Any], dict[str, str]]:
    records = {r["review_id"]: r for r in read_jsonl(path)}
    missing = set(ids) - set(records)
    if missing:
        raise SystemExit(f"{path}: {len(missing)} gold reviews have no prediction")
    raws = {i: records[i]["raw"] for i in ids}
    preds = [parse_diagnosis(raws[i]) for i in ids]
    config: dict[str, Any] = {"predictions_file": str(path.relative_to(PROJECT_ROOT))}
    latencies = [records[i]["latency_s"] for i in ids if records[i].get("latency_s") is not None]
    if latencies:
        config["latency"] = latency_stats(latencies)
    return preds, config, raws


def main() -> None:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument("--model", required=True, help="model name (results/<model>.json)")
    parser.add_argument("--predictions", type=Path, help="raw predictions JSONL (other models)")
    parser.add_argument("--config", type=Path, help="JSON with the model's run configuration")
    args = parser.parse_args()

    ids, texts, gold = load_gold()
    raws: dict[str, str] = {}
    if args.predictions:
        preds, config, raws = eval_predictions_file(args.predictions.resolve(), ids)
    elif args.model == "gemini-teacher":
        preds, config = eval_teacher(ids, texts)
    elif args.model == "tfidf-logreg":
        preds, config = eval_tfidf(ids, texts)
    else:
        parser.error(f"unknown model {args.model!r}: pass --predictions")
    if args.config:
        config["run"] = json.loads(args.config.read_text(encoding="utf-8"))

    latency = config.pop("latency", {})
    result = {
        "model": args.model,
        "evaluated_at": datetime.now(UTC).isoformat(timespec="seconds"),
        "gold_set": {"path": str(GOLD_LABELS_PATH.relative_to(PROJECT_ROOT)), "n": len(gold)},
        "metrics": compute_metrics(gold, preds) | latency,
        "config": config,
    }
    RESULTS_DIR.mkdir(exist_ok=True)
    out = RESULTS_DIR / f"{args.model}.json"
    out.write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    pred_path = RESULTS_DIR / "predictions" / f"{args.model}.jsonl"
    pred_path.unlink(missing_ok=True)
    append_jsonl(
        pred_path,
        (
            {
                "review_id": i,
                "text": t,
                "gold": g.model_dump(mode="json"),
                "pred": None if p is None else p.model_dump(mode="json"),
                "correct": p == g,
                **({"raw": raws[i]} if raws else {}),
            }
            for i, t, g, p in zip(ids, texts, gold, preds, strict=True)
        ),
    )

    m = result["metrics"]
    print(
        f"{args.model}: aspects macro-F1 {m['aspects_macro_f1']:.3f} | "
        f"main_issue macro-F1 {m['main_issue_macro_f1']:.3f} "
        f"acc {m['main_issue_accuracy']:.3f} | needs_contact F1 {m['needs_contact_f1']:.3f} | "
        f"valid JSON {m['json_valid_pct']:.1f}% | "
        f"latency {m.get('latency_ms_mean', float('nan')):.1f} ms/review\n-> {out}"
    )
    if "val_metrics" in config:
        v = config["val_metrics"]
        print(
            f"  val: aspects {v['aspects_macro_f1']:.3f} | main_issue "
            f"{v['main_issue_macro_f1']:.3f} | contact {v['needs_contact_f1']:.3f}"
        )


if __name__ == "__main__":
    main()
